    public bool relink_context_current(Control o,Settings context)
    {
        var clip=Session(o).Call("primary_clip").AsGodotObject();return o.IsInsideTree()&&o.IsVisibleInTree()&&!Field<Node>(o,"recorder").Get("recording").AsBool()&&!o.Get("_record_busy").AsBool()&&Get(context,"owner").AsGodotObject()==Session(o)&&Get(context,"document").AsGodotObject()==Document(o)&&Get(context,"revision",-1).AsInt64()==Session(o).Get("revision").AsInt64()&&Get(context,"token",-1).AsInt64()==o.Get("_relink_generation").AsInt64()&&Session(o).Get("_before").VariantType==Variant.Type.Nil&&clip!=null&&clip.Get("id").AsString()==Get(context,"focus_id","").AsString();
    }
    public void relink_source(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Finish or cancel the take before relinking audio.");return;}if(Session(o).Get("_before").VariantType!=Variant.Type.Nil){notice(o,"Finish the current edit before relinking audio.");return;}var clip=Session(o).Call("primary_clip").AsGodotObject();var actor=Session(o).Call("primary_actor").AsGodotObject();if(clip==null||actor==null)return;var source=Get(Dict(actor,"values"),"audio");if(source.VariantType!=Variant.Type.String||source.AsString().Length==0){notice(o,"Only file-backed audio clips can be relinked here. Embedded edits and sampler sources are preserved.");return;}using var edits=new AudioEditSessionOperations();if(edits.is_note_source(actor)){notice(o,"Restore this pattern's instrument samples instead of replacing its generated audio.");return;}if(!Session(o).Call("can_edit",clip.Get("id")).AsBool()){notice(o,"Unlock the clip before relinking its source.");return;}finish_automation_pass(o,"Audio relink started");long token=o.Get("_relink_generation").AsInt64()+1;o.Set("_relink_generation",token);var context=new Settings{["owner"]=Session(o),["document"]=Document(o),["revision"]=Session(o).Get("revision"),["focus_id"]=clip.Get("id"),["source"]=source,["token"]=token};var shared=new GArray();foreach(string id in edits.audio_source_clips(Session(o),clip.Get("id").AsString()))shared.Add(id);if(shared.Count<=1){o.Call("_pick_audio_relink",context,new GArray{clip.Get("id")});return;}var dialog=window(o,"Relink shared audio source",new Vector2I(600,270));var windowNode=dialog["window"].As<Window>();windowNode.SetMeta("audio_relink_window",true);var host=dialog["host"].As<Node>();label(host,shared.Count+" clips reference this source: "+source.AsString().GetFile());label(host,"Choose the scope explicitly. Every source window is checked before any clip changes. Timeline positions, trims, speed, reverse/loop state, effects and automation stay intact. Locked or incompatible clips reject the whole chosen group.");ActionButton(host,"Relink this clip only",()=>{o.Call("_pick_audio_relink",context,new GArray{context["focus_id"].AsString()});windowNode.QueueFree();});ActionButton(host,"Relink all "+shared.Count+" referencing clips",()=>{o.Call("_pick_audio_relink",context,shared);windowNode.QueueFree();});ActionButton(host,"Cancel",windowNode.QueueFree);
    }
    public void complete_relink_pick(Control o,Settings context,GArray ids,string chosen)
    {
        if(!relink_context_current(o,context)){notice(o,"The composition or selection changed while choosing a source. Start relinking again.");return;}if(chosen.Length==0||chosen=="::empty-resource::")return;var request=context.Duplicate();request["ids"]=ids.Duplicate();Work(o,"relink_probe",request["token"].AsInt64(),job=>{using var edits=new AudioEditSessionOperations();return new Settings{["context"]=request,["replacement"]=edits.probe_audio_relink(chosen,job)};});Field<Label>(o,"status").Text="Checking replacement source; the composition is unchanged.";
    }
    public void review_audio_relink(Control o,Settings data)
    {
        string error=Get(data,"error","").AsString();if(error.Length>0){notice(o,error);return;}var context=Get(data,"context",new Settings()).AsGodotDictionary();if(!relink_context_current(o,context))return;var replacement=Get(data,"replacement",new Settings()).AsGodotDictionary();using var edits=new AudioEditSessionOperations();error=edits.audio_relink_problem(Session(o),Get(context,"ids",new GArray()).AsGodotArray(),Get(context,"source","").AsString(),replacement);if(error.Length>0){notice(o,error);return;}var dialog=window(o,"Confirm audio relink",new Vector2I(620,310));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();windowNode.SetMeta("audio_relink_window",true);label(host,"Replace "+context["source"].AsString().GetFile()+" with "+replacement["path"].AsString().GetFile()+" ("+replacement["seconds"].AsDouble().ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+" seconds) in "+context["ids"].AsGodotArray().Count+" clip(s).");label(host,"The replacement fits every selected source window. Apply changes only the active file reference and source-duration metadata; clip geometry and processing stay unchanged. Original sources, embedded edits, sampler mappings and original_audio provenance are not copied or rewritten. Loop periods must match exactly. Changes form one Undo action. Reusing the same path also refreshes its cache and clears any stale transient analysis.");ActionButton(host,"Apply relink",()=>{if(complete_audio_relink(o,data))windowNode.QueueFree();});ActionButton(host,"Cancel",windowNode.QueueFree);
    }
    public bool complete_audio_relink(Control o,Settings data)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Finish or cancel the take before relinking audio.");return false;}var context=Get(data,"context",new Settings()).AsGodotDictionary();if(!relink_context_current(o,context)){notice(o,"The composition or selection changed. Start relinking again.");return false;}if(Recording(o).Call("has_pending").AsBool()){notice(o,"Finish or discard the pending automation pass before relinking.");return false;}var ids=Get(context,"ids",new GArray()).AsGodotArray();long prior=Session(o).Get("revision").AsInt64();var replacement=Get(data,"replacement",new Settings()).AsGodotDictionary();using var edits=new AudioEditSessionOperations();string error=edits.audio_relink_problem(Session(o),ids,Get(context,"source","").AsString(),replacement);if(error.Length>0){notice(o,error);return false;}var playback=Field<Node>(o,"playback");var system=playback.Get("system").AsGodotObject();var overrides=Dict(system,"clip_stream_overrides");var previous=overrides.Duplicate();var audio=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs");string path=replacement["path"].AsString();audio.Call("invalidate",path);string key=edits.audio_source_key(path);foreach(var raw in Items(Document(o),"actors")){var value=Get(Dict(raw.AsGodotObject(),"values"),"audio");if(edits.audio_source_key(value)==key)audio.Call("invalidate",value.AsString());}if(audio.Call("needs_file_preview",path).AsBool()){var model=playback.Get("model").AsGodotObject();var actors=Items(model,"actors");var clips=Items(model,"clips");for(int index=0;index<Math.Min(actors.Count,clips.Count);index++)if(edits.audio_source_key(Get(Dict(actors[index].AsGodotObject(),"values"),"audio"))==key)overrides[clips[index].AsGodotObject().Get("id")]=default(Variant);}error=edits.relink_audio_sources(Session(o),ids,Get(context,"source","").AsString(),replacement);if(error.Length>0){system.Set("clip_stream_overrides",previous);notice(o,error);return false;}o.Set("_relink_generation",o.Get("_relink_generation").AsInt64()+1);cancel_exact_playback(o);playback.Call("stop",false);o.Set("_analysis_result",new Settings());Field<Node>(o,"cache").Call("invalidate");if(Session(o).Get("revision").AsInt64()==prior)refresh_all(o);if(ids.Contains(o.Get("_wave_clip_id"))){o.Set("_wave_clip_id","");var waveform=Field<Control>(o,"waveform");waveform.Call("open",default(Variant));waveform.Set("selection",Vector2I.Zero);}Field<Label>(o,"status").Text=Session(o).Get("revision").AsInt64()!=prior?"Relinked "+ids.Count+" clip(s) without changing their windows or processing.":"Source refreshed. No document changes or Undo action were needed.";return true;
    }
